PRAGMA foreign_keys = OFF;
DROP TABLE IF EXISTS product_events; DROP TABLE IF EXISTS workflow_tasks; DROP TABLE IF EXISTS site_documents;
DROP TABLE IF EXISTS clinical_queries; DROP TABLE IF EXISTS recruitment_events; DROP TABLE IF EXISTS site_activation_events;
DROP TABLE IF EXISTS users; DROP TABLE IF EXISTS sites; DROP TABLE IF EXISTS studies; DROP TABLE IF EXISTS document_types; DROP TABLE IF EXISTS date_dim;
PRAGMA foreign_keys = ON;
CREATE TABLE studies (study_id INTEGER PRIMARY KEY, study_name TEXT, therapeutic_area TEXT, study_phase TEXT, sponsor TEXT, planned_start_date DATE, planned_end_date DATE, target_enrollment INTEGER, study_status TEXT);
CREATE TABLE sites (site_id INTEGER PRIMARY KEY, study_id INTEGER, site_name TEXT, country TEXT, region TEXT, site_tier TEXT, principal_investigator TEXT, planned_activation_date DATE, actual_activation_date DATE, site_status TEXT, enrollment_target INTEGER, FOREIGN KEY(study_id) REFERENCES studies(study_id));
CREATE TABLE users (user_id INTEGER PRIMARY KEY, site_id INTEGER, study_id INTEGER, user_role TEXT, country TEXT, signup_date DATE, user_status TEXT, FOREIGN KEY(site_id) REFERENCES sites(site_id), FOREIGN KEY(study_id) REFERENCES studies(study_id));
CREATE TABLE document_types (document_type_id INTEGER PRIMARY KEY, document_type TEXT, document_category TEXT, is_critical INTEGER);
CREATE TABLE date_dim (date_key DATE PRIMARY KEY, year INTEGER, quarter INTEGER, month INTEGER, month_name TEXT, year_month TEXT, week INTEGER, day_of_week TEXT, is_weekend INTEGER);
CREATE TABLE recruitment_events (recruitment_event_id INTEGER PRIMARY KEY, study_id INTEGER, site_id INTEGER, event_date DATE, screened_count INTEGER, screen_failed_count INTEGER, randomized_count INTEGER, withdrawn_count INTEGER, monthly_target INTEGER, FOREIGN KEY(study_id) REFERENCES studies(study_id), FOREIGN KEY(site_id) REFERENCES sites(site_id));
CREATE TABLE site_activation_events (activation_event_id INTEGER PRIMARY KEY, study_id INTEGER, site_id INTEGER, site_selected_date DATE, contract_sent_date DATE, contract_signed_date DATE, regulatory_submitted_date DATE, regulatory_approved_date DATE, site_initiation_visit_date DATE, activated_date DATE, planned_activation_date DATE, activation_status TEXT, FOREIGN KEY(study_id) REFERENCES studies(study_id), FOREIGN KEY(site_id) REFERENCES sites(site_id));
CREATE TABLE clinical_queries (query_id INTEGER PRIMARY KEY, study_id INTEGER, site_id INTEGER, subject_id TEXT, query_open_date DATE, query_resolved_date DATE, query_status TEXT, query_category TEXT, query_priority TEXT, sla_days INTEGER, FOREIGN KEY(study_id) REFERENCES studies(study_id), FOREIGN KEY(site_id) REFERENCES sites(site_id));
CREATE TABLE site_documents (document_record_id INTEGER PRIMARY KEY, study_id INTEGER, site_id INTEGER, document_type_id INTEGER, required_flag INTEGER, received_flag INTEGER, approved_flag INTEGER, due_date DATE, received_date DATE, document_status TEXT, FOREIGN KEY(study_id) REFERENCES studies(study_id), FOREIGN KEY(site_id) REFERENCES sites(site_id), FOREIGN KEY(document_type_id) REFERENCES document_types(document_type_id));
CREATE TABLE product_events (event_id INTEGER PRIMARY KEY, user_id INTEGER, site_id INTEGER, study_id INTEGER, event_timestamp DATETIME, event_date DATE, event_type TEXT, product_area TEXT, session_id TEXT, FOREIGN KEY(user_id) REFERENCES users(user_id), FOREIGN KEY(site_id) REFERENCES sites(site_id), FOREIGN KEY(study_id) REFERENCES studies(study_id));
CREATE TABLE workflow_tasks (task_id INTEGER PRIMARY KEY, study_id INTEGER, site_id INTEGER, task_type TEXT, task_created_date DATE, task_completed_date DATE, task_status TEXT, task_priority TEXT, owner_role TEXT, sla_days INTEGER, FOREIGN KEY(study_id) REFERENCES studies(study_id), FOREIGN KEY(site_id) REFERENCES sites(site_id));
CREATE INDEX idx_sites_study ON sites(study_id); CREATE INDEX idx_users_site ON users(site_id); CREATE INDEX idx_events_user ON product_events(user_id);
CREATE INDEX idx_re_event_date ON recruitment_events(event_date); CREATE INDEX idx_q_open ON clinical_queries(query_open_date); CREATE INDEX idx_q_resolved ON clinical_queries(query_resolved_date);
CREATE INDEX idx_doc_due ON site_documents(due_date); CREATE INDEX idx_task_created ON workflow_tasks(task_created_date); CREATE INDEX idx_task_completed ON workflow_tasks(task_completed_date);
